#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int n;cin>>n;
unordered_set<string>ws;
for(int i=0;i<n;++i){string w;cin>>w;ws.insert(w);}
int L=s.size();vector<bool>dp(L+1,false);dp[0]=true;
for(int i=1;i<=L;++i)for(int j=0;j<i;++j)
if(dp[j]&&ws.count(s.substr(j,i-j))){dp[i]=true;break;}
printf("%s\n",dp[L]?"YES":"NO");return 0;}

